INSERT INTO public.content_items (id, content_type, payload, sort) VALUES
('conversation-conv-intro', 'conversation-def', $json${"sid":"conv-intro","title":"Vorstellung","titleEn":"Meeting people","emoji":"👋","ctx":"Self-introduction","band":"A1-B1","closing":"Sehr schön! Bis bald!","variants":[{"id":"intro-kurs","name":"Neu im Kurs","steps":[{"n":"Hallo! Bist du neu hier im Kurs?","nEn":"Hi! Are you new here in the course?","p":"Introduce yourself briefly.","opts":[{"ref":"Ich möchte mich kurz vorstellen.","ok":true},{"t":"Ich muss mich beeilen.","en":"I have to hurry up.","ne":"मलाई हतार गर्नु पर्छ।","neR":"malai hataar garna parcha","fb":"That is about hurrying - introduce yourself instead!"}]},{"n":"Freut mich! Woher kommst du?","nEn":"Nice to meet you! Where are you from?","p":"Say where you come from.","opts":[{"ref":"Ich bin Aisha und komme aus Nepal.","ok":true},{"t":"Ich habe heute viel gearbeitet.","en":"I worked a lot today.","ne":"मैले आज धेरै काम गरें।","neR":"maile aaja dherai kaam garen","fb":"Work talk will not tell her where you are from!"}]},{"n":"Und? Sprichst du schon gut Deutsch?","nEn":"And? Do you already speak German well?","p":"Be modest about your level.","opts":[{"ref":"Ich kann ein bisschen Deutsch sprechen.","ok":true},{"t":"Ich gehe heute einkaufen.","en":"I am going shopping today.","ne":"म आज किनमेल गर्न जान्छु।","neR":"ma aaja kinmel garna jaanchhu","fb":"Shopping plans do not answer a language question!"}]}]},{"id":"intro-zug","name":"Platz im Zug","steps":[{"n":"Entschuldigung, ist dieser Platz frei?","nEn":"Excuse me, is this seat free?","p":"Offer the seat politely.","opts":[{"t":"Ja, natürlich! Bitte setzen Sie sich.","en":"Yes, of course! Please take a seat.","ne":"जा, अवश्य! कृपया बस्नुहोस्।","neR":"ja awashya kripaya basnuhos","ok":true},{"ref":"Ich steige an der nächsten Haltestelle aus.","fb":"That is about getting off - offer the seat first!"}]},{"n":"Danke schön! Sag mal, woher kommst du?","nEn":"Thank you! Tell me, where are you from?","p":"Say where you come from.","opts":[{"ref":"Ich bin Aisha und komme aus Nepal.","ok":true},{"t":"Der Zug fährt gleich ab.","en":"The train leaves soon.","ne":"ट्रेन चाँडै छुट्छ।","neR":"tren chaadai chhutcha","fb":"Timetables later - answer the question!"}]},{"n":"Interessant! Und wie lange wohnst du schon hier?","nEn":"Interesting! And how long have you lived here?","p":"Say for how long you have been living here.","opts":[{"ref":"Ich wohne seit drei Jahren in Deutschland.","ok":true},{"t":"Ich stehe um sechs Uhr auf.","en":"I get up at six o'clock.","ne":"म बिहान छ बजे उठ्छु।","neR":"ma bihaan chha baje uthchhu","fb":"Wake-up times do not answer this!"}]}]},{"id":"intro-freitag","name":"Smalltalk am Freitag","steps":[{"n":"Endlich Freitag! Was machst du am Wochenende?","nEn":"Finally Friday! What are you doing this weekend?","p":"Say what you are looking forward to.","opts":[{"ref":"Ich freue mich auf das Wochenende.","ok":true},{"ref":"Ich rufe dich morgen an.","fb":"Calling is nice - but say what you are looking forward to!"}]},{"n":"Klingt gut! Ich glaube, wir kennen uns noch nicht, oder?","nEn":"Sounds good! I think we do not know each other yet, do we?","p":"Greet her politely.","opts":[{"ref":"Freut mich, Sie kennenzulernen.","ok":true},{"ref":"Der Kurs fängt um neun Uhr an.","fb":"Schedules can wait - greet her first!"}]}]}]}$json$::jsonb, 0),
('conversation-conv-cafe', 'conversation-def', $json${"sid":"conv-cafe","title":"Im Café","titleEn":"At the café","emoji":"☕","ctx":"Ordering food and drink","band":"A1-A2","closing":"Danke, kommen Sie bald wieder!","variants":[{"id":"cafe-kaffee","name":"Zwei Kaffee","steps":[{"n":"Guten Tag! Was möchten Sie?","nEn":"Hello! What would you like?","p":"Order two coffees.","opts":[{"ref":"Ich möchte bitte zwei Kaffee.","ok":true,"reaction":"Ja, gern! Zwei Kaffee.","reactionEn":"Yes, gladly! Two coffees."},{"ref":"Ich möchte bitte die Rechnung.","fb":"The bill comes at the end - order first!"},{"t":"Ich wohne in Berlin.","en":"I live in Berlin.","ne":"म बर्लिनमा बस्छु।","neR":"ma berlin maa baschhu","fb":"Your address is not on the menu!"}]},{"n":"Möchten Sie auch etwas zu essen?","nEn":"Would you like anything to eat as well?","p":"Politely decline.","opts":[{"t":"Nein, danke. Nur den Kaffee.","en":"No thanks, just the coffee.","ne":"नाइँ, धन्यवाद। कफी मात्र।","neR":"naai dhanyabaad kafi maatra","ok":true,"reaction":"Alles klar, nur der Kaffee.","reactionEn":"Alright, just the coffee."},{"t":"Ja, ein Taxi, bitte.","en":"Yes, a taxi please.","ne":"जा, ट्याक्सी पाइयोस्।","neR":"ja taxi paaiyos","fb":"A taxi? We are in a café!"}]},{"n":"Sehr gern. Das macht dann 4,50 Euro.","nEn":"With pleasure. That comes to 4.50 euros.","p":"Ask for the bill.","opts":[{"ref":"Ich möchte bitte die Rechnung.","ok":true,"reaction":"Gerne, einen Moment bitte.","reactionEn":"Gladly, one moment please."},{"ref":"Wo ist bitte der Bahnhof?","fb":"You are navigating the menu, not the city!"}]}]},{"id":"cafe-pizza","name":"Pizza bestellen","steps":[{"n":"Herzlich willkommen bei uns!","en":"A warm welcome!","p":"Ask to see the menu.","opts":[{"ref":"Kann ich bitte die Speisekarte sehen?","ok":true},{"ref":"Können Sie mir bitte helfen?","fb":"You do not need help - you are hungry!"}]},{"n":"Natürlich, hier bitte. Und was darf es sein?","en":"Of course, here you go. What will it be?","p":"Order a pizza.","opts":[{"t":"Ich möchte bitte eine Pizza.","en":"I would like a pizza, please.","ne":"कृपया मलाई पिज्जा चाहियो।","neR":"kripaya malai pizza chaahiyo","ok":true},{"t":"Ich hätte gern ein Doppelzimmer.","en":"I would like a double room.","ne":"मलाई डबल कोठा चाहियो।","neR":"malai double kothaa chaahiyo","fb":"That is hotel talk - we are ordering food!"}]},{"n":"Ausgezeichnete Wahl. Sonst noch etwas?","en":"Excellent choice. Anything else?","p":"Say that is everything.","opts":[{"t":"Nein, das ist alles. Danke!","en":"No, that is all. Thank you!","ne":"नाइँ, यति मात्र हो। धन्यवाद।","neR":"naai yo maatra ho dhanyabaad","ok":true},{"ref":"Was kostet das?","fb":"Save that question for the bill."}]}]},{"id":"cafe-durst","name":"Durst im Café","steps":[{"n":"Uff, ich habe heute so einen Durst!","en":"Uff, I am so thirsty today!","p":"Ask your friend what she wants to drink.","opts":[{"ref":"Was möchtest du trinken?","ok":true},{"t":"Darf ich dich etwas fragen?","en":"May I ask you something?","ne":"के म तिमीलाई सोध्न सक्छु?","neR":"ke ma timilaai sodhna sakchhu","fb":"Questions later - offer her a drink first!"}]},{"n":"Ein Mineralwasser, bitte. Und für dich?","en":"A mineral water, please. And for you?","p":"Order your own drink.","opts":[{"t":"Ich nehme einen Apfelsaft.","en":"I will take an apple juice.","ne":"म एउटा स्याउको जूस लिन्छु।","neR":"ma euta syaauko juice linchu","ok":true,"reaction":"Sehr gut, das nehme ich auch!","reactionEn":"Very good, I will take that too!"},{"t":"Ich muss zur Besuch kommen.","en":"I have to come to the visit.","ne":"म भ्रमणमा आउनु पर्छ।","neR":"ma bhramanmaa aaunu parcha","fb":"Buses are dry - pick a drink!"}]}]},{"id":"cafe-einladen","name":"Auf einen Kaffee","steps":[{"n":"Schön, dich zu sehen! Hast du Lust, mit mir etwas zu trinken?","nEn":"Nice to see you! Fancy getting a drink with me?","p":"Accept and say it is your treat.","opts":[{"t":"Gern! Ich lade dich ein.","en":"Gladly! It is on me.","ne":"खुसीले! म निम्तो दिन्छु।","neR":"khusile ma ninto dinchu","ok":true},{"t":"Ich muss mich beeilen.","en":"I have to hurry up.","ne":"मलाई हतार गर्नु पर्छ।","neR":"malai hataar garna parcha","fb":"Then hurry home - but you wanted to stay!"}]},{"n":"Wie lieb! Bestell du schon mal an der Theke.","nEn":"How sweet! Order at the counter already.","p":"Order two coffees.","opts":[{"ref":"Ich möchte bitte zwei Kaffee.","ok":true},{"ref":"Ich soll den Schlüssel an der Rezeption abgeben.","fb":"Hotel business again - we want coffee!"}]}]}]}$json$::jsonb, 1),
('conversation-conv-hotel', 'conversation-def', $json${"sid":"conv-hotel","title":"Hotel-Check-in","titleEn":"Hotel check-in","emoji":"🏨","ctx":"Hotel check-in","band":"A2-B1","closing":"Auf Wiedersehen und gute Reise!","variants":[{"id":"hotel-buchen","name":"Zimmer buchen","steps":[{"from":"me","n":"Haben Sie noch ein Zimmer frei?","nEn":"Do you still have a room available?","p":"You walk into the hotel. Ask the receptionist for a room.","opts":[{"ref":"Haben Sie noch ein Zimmer frei?","ok":true,"reaction":"Guten Abend! Ja, zum Glück ist noch etwas frei.","reactionEn":"Good evening! Yes, luckily something is still free."},{"ref":"Wo ist bitte der Bahnhof?","fb":"You are checking in, not asking directions!"}]},{"n":"Ja, zum Glück ist noch etwas frei. Für wie viele Nächte?","nEn":"Yes, luckily something is free. For how many nights?","p":"Book a double room for two nights.","opts":[{"ref":"Ich hätte gern ein Doppelzimmer für zwei Nächte.","ok":true,"reaction":"Sehr gern, ein Doppelzimmer für zwei Nächte.","reactionEn":"Very well, a double room for two nights."},{"ref":"Ich möchte mich kurz ausruhen.","fb":"Resting comes after booking!"}]}]},{"id":"hotel-formular","name":"Formular ausfüllen","steps":[{"n":"Hier ist Ihr Schlüssel - Zimmer 12, zweiter Stock.","nEn":"Here is your key - room 12, second floor.","p":"Ask about the paperwork.","opts":[{"ref":"Muss ich dieses Formular ausfüllen?","ok":true},{"ref":"Kannst du bitte das Fenster aufmachen?","fb":"Windows can wait - ask about check-in first."}]},{"n":"Nur Ihren Namen und Ihre Adresse, bitte.","nEn":"Just your name and address, please.","p":"Hand over your ID politely.","opts":[{"t":"Gern, hier ist mein Ausweis.","en":"Sure, here is my ID.","ne":"ठीक छ, यहाँ मेरो परिचयपत्र हो।","neR":"thik chha yahaa mero parichaypatra ho","ok":true},{"ref":"Wir müssen am Hauptbahnhof umsteigen.","fb":"Trains later - reception first."}]}]},{"id":"hotel-abreise","name":"Abreise","steps":[{"n":"Guten Morgen! Wie hat Ihnen das Zimmer gefallen?","nEn":"Good morning! How did you like the room?","p":"Say you liked it very much.","opts":[{"t":"Sehr gut, danke!","en":"Very good, thank you!","ne":"धेरै राम्रो, धन्यवाद!","neR":"dherai raamro dhanyabaad","ok":true},{"ref":"Der Zug fährt in zwanzig Minuten ab.","fb":"True - but answer about the room first!"}]},{"n":"Das freut mich! Kann ich sonst noch etwas für Sie tun?","nEn":"Glad to hear! Anything else I can do for you?","p":"Say you must hand in the key.","opts":[{"ref":"Ich soll den Schlüssel an der Rezeption abgeben.","ok":true},{"ref":"Wollen wir heute zusammen essen gehen?","fb":"Dinner sounds great - but you are checking out!"}]},{"n":"Natürlich. Gute Reise!","nEn":"Of course. Have a good trip!","p":"Thank the staff for their help.","opts":[{"ref":"Ich möchte mich bei Ihnen für die Hilfe bedanken.","ok":true},{"ref":"Ich muss mich beeilen.","fb":"Then hurry - but say thank you first!"}]}]}]}$json$::jsonb, 2),
('conversation-conv-shop', 'conversation-def', $json${"sid":"conv-shop","title":"Einkaufen","titleEn":"Shopping","emoji":"🛒","ctx":"Shopping","band":"A1","closing":"Danke für Ihren Einkauf! Auf Wiedersehen!","variants":[{"id":"shop-preis","name":"Preis fragen","steps":[{"n":"Hallo! Kann ich Ihnen behilflich sein?","nEn":"Hello! Can I help you?","p":"Ask the price of an item.","opts":[{"ref":"Was kostet das?","ok":true},{"ref":"Wie bitte?","fb":"You heard fine - ask about the price."}]},{"n":"Das kostet 19,99 Euro. Nehmen Sie es mit?","nEn":"That is 19.99 euros. Will you take it?","p":"Say yes, you will take it.","opts":[{"t":"Ja, ich nehme es.","en":"Yes, I will take it.","ne":"जा, म यो लिन्छु।","neR":"ja ma yo linchu","ok":true},{"ref":"Ich muss mich für den Kurs anmelden.","fb":"Course registration at the shop? No."}]}]},{"id":"shop-karte","name":"Bar oder Karte","steps":[{"n":"Das macht zusammen 12,50 Euro.","nEn":"That comes to 12.50 euros altogether.","p":"Pay by card.","opts":[{"t":"Mit Karte, bitte.","en":"By card, please.","ne":"कार्डबाट, कृपया।","neR":"kaardbaata kripaya","ok":true},{"ref":"Zahlen Sie mit Karte oder bar?","fb":"Careful - YOU are the customer here!"}]},{"n":"Sehr gern. Hier ist Ihre Quittung.","nEn":"With pleasure. Here is your receipt.","p":"Thank her and say goodbye.","opts":[{"t":"Danke, auf Wiedersehen!","en":"Thanks, goodbye!","ne":"धन्यवाद, फेरि भेटौंला।","neR":"dhanyabaad pheri bhetaunla","ok":true},{"ref":"Kommst du morgen mit?","fb":"Shopping done - no plans needed here."}]}]},{"id":"shop-bummel","name":"Stadtbummel","steps":[{"n":"Schönes Wetter heute! Was haben Sie vor?","nEn":"Lovely weather today! What are your plans?","p":"Say you are going shopping today.","opts":[{"ref":"Ich gehe heute einkaufen.","ok":true},{"ref":"Wir müssen am Hauptbahnhof umsteigen.","fb":"Train problems are not weekend plans."}]},{"n":"Dann viel Spaß beim Shoppen!","nEn":"Have fun shopping then!","p":"Say you will take the bus into town.","opts":[{"ref":"Ich fahre mit dem Bus in die Stadt.","ok":true},{"t":"Ich kaufe eine Pizza.","en":"I will buy a pizza.","ne":"म पिज्जा किन्छु।","neR":"ma pizza kinchu","fb":"That is café territory - buses were the topic!"}]}]}]}$json$::jsonb, 3),
('conversation-conv-reisen', 'conversation-def', $json${"sid":"conv-reisen","title":"Unterwegs","titleEn":"On the road","emoji":"🚆","ctx":"Traveling","band":"A1-B1","closing":"Alles klar, gute Reise!","variants":[{"id":"reisen-weg","name":"Nach dem Weg fragen","steps":[{"n":"Sie sehen so verloren aus. Kann ich helfen?","nEn":"You look so lost. Can I help?","p":"Ask for the railway station.","opts":[{"ref":"Wo ist bitte der Bahnhof?","ok":true},{"ref":"Haben Sie noch ein Zimmer frei?","fb":"No rooms here - ask for directions."}]},{"n":"Gleich dort drüben, hinter der Ampel.","nEn":"Right over there, behind the traffic light.","p":"Thank them warmly.","opts":[{"t":"Vielen Dank für Ihre Hilfe!","en":"Many thanks for your help!","ne":"तपाईंको सहयोगका लागि धन्यवाद!","neR":"tapaaiko sahayogko lagi dhanyabaad","ok":true},{"ref":"Ich steige an der nächsten Haltestelle aus.","fb":"You are walking there, not riding."}]}]},{"id":"reisen-zug","name":"Mit dem Zug fahren","steps":[{"n":"Weißt du, wann unser Zug geht?","nEn":"Do you know when our train leaves?","p":"Tell him it leaves in twenty minutes.","opts":[{"ref":"Der Zug fährt in zwanzig Minuten ab.","ok":true},{"ref":"Der Kurs fängt um neun Uhr an.","fb":"Wrong timetable - think train, not course!"}]},{"n":"Oh! Müssen wir irgendwo umsteigen?","nEn":"Oh! Do we have to change anywhere?","p":"Say you have to change at the main station.","opts":[{"ref":"Wir müssen am Hauptbahnhof umsteigen.","ok":true},{"t":"Ich stehe um sechs Uhr auf.","en":"I get up at six o'clock.","ne":"म बिहान छ बजे उठ्छु।","neR":"ma bihana chha baje uthchhu","fb":"Bedtime will not catch our train!"}]},{"n":"Und wo genau steigen wir aus?","nEn":"And where exactly do we get off?","p":"Say you get off at the next stop.","opts":[{"ref":"Ich steige an der nächsten Haltestelle aus.","ok":true},{"ref":"Ich gehe heute einkaufen.","fb":"Not now - we are on the train!"}]}]},{"id":"reisen-besuch","name":"Besuch angekündigt","steps":[{"n":"Ich komme nächste Woche zu dir! Ich buche gleich den Zug.","nEn":"I am coming to visit next week! I will book the train right away.","p":"Ask when her train arrives.","opts":[{"ref":"Wann kommt dein Zug an?","ok":true},{"ref":"Wo ist bitte der Bahnhof?","fb":"She knows the plan - ask about HER arrival time."}]},{"n":"Samstag um 15:30 Uhr. Holst du mich ab?","nEn":"Saturday at 3:30 pm. Will you pick me up?","p":"Say yes, you will be at the station.","opts":[{"t":"Ja, klar! Ich bin am Bahnhof.","en":"Yes, sure! I will be at the station.","ne":"जा, म रेलवे स्टेशनमा हुन्छु।","neR":"ja ma relay station maa hunchhu","ok":true},{"ref":"Könntest du mich am Bahnhof abholen?","fb":"Careful - SHE asked YOU to pick HER up!"}]}]},{"id":"reisen-ausflug","name":"Ausflug in die Berge","steps":[{"n":"Was machen wir eigentlich am Wochenende?","nEn":"So what are we doing this weekend?","p":"Suggest going to the mountains.","opts":[{"ref":"Wir fahren am Wochenende in die Berge.","ok":true},{"ref":"Muss ich dieses Formular ausfüllen?","fb":"Paperwork on a day trip? No way."}]},{"n":"Super Idee! Nehmen wir das Auto?","nEn":"Great idea! Should we take the car?","p":"Suggest taking the bus instead.","opts":[{"ref":"Ich fahre mit dem Bus in die Stadt.","ok":true},{"ref":"Gibt es hier einen Parkplatz?","fb":"Parking is irrelevant if we take the bus."}]}]}]}$json$::jsonb, 4),
('conversation-conv-buero', 'conversation-def', $json${"sid":"conv-buero","title":"Im Büro","titleEn":"At the office","emoji":"💼","ctx":"Workplace chat","band":"A1-B1","closing":"Super, danke dir! Bis morgen!","variants":[{"id":"buero-start","name":"Erster Tag","steps":[{"n":"Willkommen im Team! Der Einführungskurs startet morgen.","nEn":"Welcome to the team! The induction course starts tomorrow.","p":"Say what time it starts.","opts":[{"ref":"Der Kurs fängt um neun Uhr an.","ok":true},{"ref":"Ich muss mich an das neue Umfeld gewöhnen.","fb":"True on day one - but answer the TIME question."}]},{"n":"Alles klar. Brauchst du noch etwas?","nEn":"All right. Do you need anything else?","p":"Say you still have to register for the course.","opts":[{"ref":"Ich muss mich für den Kurs anmelden.","ok":true},{"ref":"Ich soll den Schlüssel an der Rezeption abgeben.","fb":"Reception business - focus on the course."}]},{"n":"Kein Problem. Die erste Zeit ist immer ungewohnt.","nEn":"No problem. The beginning always feels unfamiliar.","p":"Agree - say you have to get used to the new environment.","opts":[{"ref":"Ich muss mich an das neue Umfeld gewöhnen.","ok":true},{"ref":"Ich bin mit dem Ergebnis sehr zufrieden.","fb":"Save that for the project review."}]}]},{"id":"buero-projekt","name":"Projektbesprechung","steps":[{"n":"Wie läuft eigentlich unser Projekt?","nEn":"How is our project actually going?","p":"Say you would rather talk about it later.","opts":[{"ref":"Wir sprechen später über das Projekt.","ok":true},{"ref":"Ich freue mich auf das Wochenende.","fb":"Weekend joy - but your boss is asking!"}]},{"n":"Schön zu hören! Den Rest besprechen wir morgen.","nEn":"Good to hear! We will discuss the rest tomorrow.","p":"Offer to talk through the process later.","opts":[{"ref":"Wir können uns später über den Ablauf unterhalten.","ok":true},{"t":"Ich rufe dann den Kunden an.","en":"Then I will call the client.","ne":"त्यसपछि म ग्राहकलाई फोन गर्छु।","neR":"tyaspachi ma graahaklai phon 