('conv-vocab-0', 'conversation-vocab', $json${"german_text":"Ich bin Aisha und komme aus Nepal.","cefr_level":"A1","grammar_focus":"Preposition: aus + Dativ","context_situation":"Self-introduction","translations":{"en":"My name is Aisha and I come from Nepal.","ne":"मेरो नाम आयशा हो र म नेपालबाट आएको छु।","ne_roman":"mero naam aasha ho ra ma nepalbata aaeko chhu"}}$json$::jsonb, 0),
('conv-vocab-1', 'conversation-vocab', $json${"german_text":"Freut mich, Sie kennenzulernen.","cefr_level":"A1","grammar_focus":"Reflexive verb: sich freuen","context_situation":"Self-introduction","translations":{"en":"Pleased to meet you.","ne":"तपाईंलाई भेटेर खुसी लाग्यो।","ne_roman":"tapailai bhetera khushi laagyo"}}$json$::jsonb, 1),
